-- STUDENT <-> TEACHER CONTACT (conversation): ContactMessages = the opening
-- question, ContactReplies = follow-up messages from the teacher OR the student.
--
-- Safe to run multiple times (IF NOT EXISTS everywhere). Matches the
-- AddContactMessages migration exactly -- run ONE of the two against a given
-- database, never both.

CREATE TABLE IF NOT EXISTS "ContactMessages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TeacherId" integer NOT NULL,
    "StudentId" integer NOT NULL,
    "Text" text NOT NULL,
    "ImageUrl" text NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "EditedAt" timestamp with time zone NULL,
    "LastActivityAt" timestamp with time zone NOT NULL,
    "IsReadByTeacher" boolean NOT NULL,
    CONSTRAINT "FK_ContactMessages_Students_StudentId"
        FOREIGN KEY ("StudentId") REFERENCES "Students" ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "ContactReplies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ContactMessageId" integer NOT NULL,
    "TeacherId" integer NOT NULL,
    "IsFromTeacher" boolean NOT NULL,
    "Text" text NOT NULL,
    "ImageUrl" text NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "EditedAt" timestamp with time zone NULL,
    CONSTRAINT "FK_ContactReplies_ContactMessages_ContactMessageId"
        FOREIGN KEY ("ContactMessageId") REFERENCES "ContactMessages" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_ContactMessages_StudentId" ON "ContactMessages" ("StudentId");
CREATE INDEX IF NOT EXISTS "IX_ContactMessages_TeacherId_StudentId" ON "ContactMessages" ("TeacherId", "StudentId");
CREATE INDEX IF NOT EXISTS "IX_ContactMessages_TeacherId_IsReadByTeacher_LastActivityAt"
    ON "ContactMessages" ("TeacherId", "IsReadByTeacher", "LastActivityAt");
CREATE INDEX IF NOT EXISTS "IX_ContactReplies_ContactMessageId_CreatedAt" ON "ContactReplies" ("ContactMessageId", "CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_ContactReplies_TeacherId" ON "ContactReplies" ("TeacherId");
